-- Applied to KADUKOV-TECH only. Private product-image bucket.
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('catalog-photos','catalog-photos',false,2097152,array['image/jpeg']::text[]);
create policy catalog_photos_admin_read on storage.objects for select to authenticated using (bucket_id='catalog-photos' and (select auth.jwt()->'app_metadata'->>'catalog_role')='admin' and (select auth.jwt()->>'aal')='aal2' and name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[1-5][.]jpg$');
create policy catalog_photos_admin_insert on storage.objects for insert to authenticated with check (bucket_id='catalog-photos' and (select auth.jwt()->'app_metadata'->>'catalog_role')='admin' and (select auth.jwt()->>'aal')='aal2' and name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[1-5][.]jpg$' and exists (select 1 from public.catalog_products p where p.id::text=split_part(storage.objects.name,'/',1)));
create policy catalog_photos_admin_delete on storage.objects for delete to authenticated using (bucket_id='catalog-photos' and (select auth.jwt()->'app_metadata'->>'catalog_role')='admin' and (select auth.jwt()->>'aal')='aal2' and name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[1-5][.]jpg$');
